// Embedded base64 data URIs for official logos (Claude, Codex, Cursor, Git)
// Guaranteed to load immediately without external file requests.
;(function () {
  const LOGO_SRC = {
    claude: "data:image/png;base64,",
    codex: "data:image/png;base64,",
    cursor: "data:image/png;base64,",
    git: "data:image/png;base64,",
  }
  const LOGOS = {}
  for (const [k, src] of Object.entries(LOGO_SRC)) {
    if (typeof Image !== 'undefined') {
      const img = new Image()
      img.src = src
      LOGOS[k] = img
    }
  }
  window.LAUNCH_LOGOS = LOGOS
})()
